import meta from './image-meta.json';

/**
 * Registry of the photographs supplied by the studio (see /public/images).
 * Alt text lives in the translation files under `Images.<key>`.
 * Dimensions and blur placeholders are generated by `npm run images`.
 */
export const assetKeys = [
  'pergola',
  'stairGarden',
  'bunaBar',
  'basin',
  'yale',
  'redRoom',
  'cactus',
  'kitchen',
  'stoneSteps',
  'overhead',
] as const;

export type AssetKey = (typeof assetKeys)[number];

export interface Asset {
  key: AssetKey;
  src: string;
  width: number;
  height: number;
  blurDataURL: string;
}

export function getAsset(key: AssetKey): Asset {
  const m = (meta as Record<string, { width: number; height: number; blur: string }>)[key];
  return {
    key,
    src: `/images/${key}.webp`,
    width: m.width,
    height: m.height,
    blurDataURL: m.blur,
  };
}
